# -*- coding: utf-8 -*-
"""Checks the artifacts generated by build_erx_seo_master_upgrader.py against real erx.vn slugs."""
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT_JS = ROOT / "pm_assets" / "erx_seo_master_upgrader.js"
OUT_SITEMAP = ROOT / "pm_assets" / "sitemap-erx-master.txt"

# Menu pages on erx.vn (slug == CMS alias == URL path), verified live on 2026-10-30
REAL_MENU_SLUGS = [
    "kien-thuc", "hoi-thao", "dao-tao-doanh-nghiep", "phan-mem", "hop-tac-viec-lam", "lien-he",
    "gioi-thieu", "mau-file-quan-ly-excel", "excel-functions", "excel-function", "excel-365",
    "excel-vba", "sql-in-excel", "dashboard-automated-report", "power-bi", "supply-chain-management",
    "procurement-management", "planning-management", "warehouse-management", "logistics-management",
    "python-for-supply-chain", "project-management", "tro-thanh-giang-vien-cung-erx",
    "thong-tin-tuyen-sinh", "tin-quan-trong",
]
# Hub URLs that returned 404 live
DEAD_HUB_SLUGS = ["tuyen-dung", "excel", "cac-ham-excel-365", "sql", "inventory-management"]


def _build():
    subprocess.run([sys.executable, str(ROOT / "build_erx_seo_master_upgrader.py")], check=True, cwd=ROOT,
                   capture_output=True)


def _window_json(name):
    text = OUT_JS.read_text(encoding="utf-8")
    m = re.search(rf"window\.{name} = (\{{.*?\}});\n", text, re.S)
    assert m, name
    return json.loads(m.group(1))


def _head_script():
    text = OUT_JS.read_text(encoding="utf-8")
    m = re.search(r"window\.ERX_HEAD_SEO_SCHEMA_SCRIPT = (\".*?\");\n", text, re.S)
    assert m
    script = json.loads(m.group(1))
    assert 'id="erx-seo-schema-upgrader"' in script
    return script


def test_builder_runs_and_every_real_menu_slug_has_seo_entry():
    _build()
    menu = _window_json("ERX_MENU_SEO_MAP")
    head = _head_script()
    missing = []
    for slug in REAL_MENU_SLUGS:
        in_menu = slug in menu
        in_head_only = f'"{slug}"' in head
        if not (in_menu or in_head_only):
            missing.append(slug)
    assert missing == []


def test_all_titles_fit_in_65_chars():
    menu = _window_json("ERX_MENU_SEO_MAP")
    workshop = _window_json("ERX_WORKSHOP_SEO_MAP")
    too_long = {k: len(v["meta_title"]) for k, v in {**menu, **workshop}.items() if len(v["meta_title"]) > 65}
    assert too_long == {}


def test_master_sitemap_has_no_known_dead_hub_urls_and_lists_real_ones():
    urls = OUT_SITEMAP.read_text(encoding="utf-8").split()
    slugs = {u.rsplit("/", 1)[-1].removesuffix(".html") for u in urls}
    assert not (set(DEAD_HUB_SLUGS) & slugs)
    assert {"hop-tac-viec-lam", "sql-in-excel", "warehouse-management", "excel-365"} <= slugs


def test_head_script_handles_noindex_and_lien_he0():
    head = _head_script()
    assert "danh-sach-ua-thich" in head and "noindex" in head
    assert '"lien-he0"' in head
